 "content": "def transform(grid):
    """Draw color-4 vertical rays where top and bottom edge marks align,
    stopping above the full-width horizontal separator."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    if h < 3 or not w:
        return out

    # The divider is the first interior row filled with a single nonzero color.
    divider = next(
        (r for r in range(1, h - 1)
         if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])),
        h - 1,
    )
    for c in range(w):
        color = grid[0][c]
        if color != 0 and grid[-1][c] == color:
            for r in range(1, divider):
                if grid[r][c] == 0:
                    out[r][c] = 4
    return out
